package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

public class CommandLineHasOptionTest {

    // Helper subclass to simulate a deprecated Option by overriding isDeprecated()
    static class DeprecatedOption extends Option {
        public DeprecatedOption(final String option, final String description) {
            super(option, description);
        }

        @Override
        public boolean isDeprecated() {
            return true;
        }
    }

    // Helper to instantiate CommandLine via its private constructor
    private CommandLine createCommandLine(final List<Option> options, final Consumer<Option> deprecatedHandler) throws Exception {
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, Consumer.class);
        ctor.setAccessible(true);
        List<String> args = new ArrayList<>();
        return ctor.newInstance(args, options, deprecatedHandler);
    }

    @Test
    public void testHasOption_presentAndDeprecated_invokesHandler() throws Exception {
        // Arrange
        DeprecatedOption deprecatedOpt = new DeprecatedOption("x", "deprecated option");
        List<Option> opts = new ArrayList<>();
        opts.add(deprecatedOpt);

        AtomicBoolean handlerCalled = new AtomicBoolean(false);
        Consumer<Option> handler = o -> handlerCalled.set(true);

        CommandLine cmd = createCommandLine(opts, handler);

        // Act
        boolean result = cmd.hasOption(deprecatedOpt);

        // Assert
        assertTrue(result, "hasOption should return true when the option is present");
        assertTrue(handlerCalled.get(), "deprecated handler should have been invoked for a deprecated option");
    }

    @Test
    public void testHasOption_presentAndNotDeprecated_doesNotInvokeHandler() throws Exception {
        // Arrange
        Option normalOpt = new Option("b", "normal option");
        List<Option> opts = new ArrayList<>();
        opts.add(normalOpt);

        AtomicBoolean handlerCalled = new AtomicBoolean(false);
        Consumer<Option> handler = o -> handlerCalled.set(true);

        CommandLine cmd = createCommandLine(opts, handler);

        // Act
        boolean result = cmd.hasOption(normalOpt);

        // Assert
        assertTrue(result, "hasOption should return true when the option is present");
        assertFalse(handlerCalled.get(), "deprecated handler should NOT be invoked for a non-deprecated option");
    }

    @Test
    public void testHasOption_notPresent_returnsFalseAndDoesNotInvokeHandler() throws Exception {
        // Arrange
        Option presentOpt = new Option("c", "present option");
        Option searchedOpt = new Option("d", "searched option"); // different instance, not in list
        List<Option> opts = new ArrayList<>();
        opts.add(presentOpt);

        AtomicBoolean handlerCalled = new AtomicBoolean(false);
        Consumer<Option> handler = o -> handlerCalled.set(true);

        CommandLine cmd = createCommandLine(opts, handler);

        // Act
        boolean result = cmd.hasOption(searchedOpt);

        // Assert
        assertFalse(result, "hasOption should return false when the option is not present");
        assertFalse(handlerCalled.get(), "deprecated handler should NOT be invoked when option is absent");
    }

    @Test
    public void testHasOption_deprecatedWithNullHandler_doesNotThrow() throws Exception {
        // Arrange
        DeprecatedOption deprecatedOpt = new DeprecatedOption("z", "deprecated option");
        List<Option> opts = new ArrayList<>();
        opts.add(deprecatedOpt);

        // Provide null handler to ensure handleDeprecated handles null safely
        CommandLine cmd = createCommandLine(opts, null);

        // Act & Assert: should not throw and should return true
        assertTrue(cmd.hasOption(deprecatedOpt), "hasOption should return true even if deprecatedHandler is null");
    }
}

